import{z as A,x as p,o as t,c as n,q as E,j as B,D as e,d as r,s as o,S as i}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"RoPE 的频率、基数与长上下文","description":"","frontmatter":{"title":"RoPE 的频率、基数与长上下文","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rope-frequency.md","filePath":"llm/rope-frequency.md","lastUpdated":1791413859000}'),l={name:"llm/rope-frequency.md"};function h(d,a,m,_,b,D){const s=p("Mermaid");return t(),n("div",null,[a[2]||(a[2]=E('<h1 id="rope-的频率、基数与长上下文" tabindex="-1">RoPE 的频率、基数与长上下文 <a class="header-anchor" href="#rope-的频率、基数与长上下文" aria-label="Permalink to &quot;RoPE 的频率、基数与长上下文&quot;">​</a></h1><div class="epigraph"><p>$\\theta_i = \\mathrm{base}^{-2i/d}$ 决定每一维转多快；改基数是在改长程维度何时开始错位。</p><footer>RoPE 频谱；NTK / YaRN 仅作为改频率的动机，不作专述</footer></div><p><a href="/llm/rope">上一课</a>对 Q、K 的成对维度做位置相关的二维旋转，使 \\(q_m^{\\top}k_n\\) 只通过旋转差依赖 \\(n-m\\)。相对恒等式对任意距离成立，训练却只覆盖一段距离。缺口是 \\(\\theta_i\\) 与基数：哪一维在多长的跨度上仍可分辨。加长上下文是在要更大的 \\(|n-m|\\)，必须让足够多的慢维在新距离上尚未转乱。改 base、NTK、YaRN 都是在动这条谱，不是换一套位置哲学。本课停在频谱与基数，不重写旋转群把绝对角差成相对角的那一步。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RoPE 的相对恒等式对任意距离成立，但训练只在 \\(0 \\le |n-m| \\lt L_{\\mathrm{train}}\\) 的距离上见到过匹配分数。推到更长上下文，新的是<strong>更大的相对距离</strong>，不是新的绝对下标。更大距离意味着每个平面上的转角 $ |n-m|\\theta_i $ 进入训练时没见过的区间，尤其是中高频平面会转过训练时从未对齐过的相位。</p><p>于是长上下文问题在 RoPE 里具体化为频谱问题：\\(\\theta_i\\) 太大，远距离上几乎所有平面都转乱，位置信息死掉，注意力退化为与距离无关的内容匹配（或噪声）；\\(\\theta_i\\) 太小，近距离上各平面几乎不转，模型分不清相邻与隔开几十步。默认 \\(\\mathrm{base}=10000\\) 是为原始训练长度选的折中。改上下文窗口而不改频谱，等于拿旧尺子量新距离。</p><p>本篇只讨论频率与基数：它们如何定义、如何对应「哪一维负责多长的跨度」，以及为什么人们用改 base、NTK 缩放、YaRN 去碰这根轴。YaRN 与 NTK 的完整算法、损失和注意力温度，留给它们自己的条目。</p><p><span class="marginnote">恒等式 \\(q^\\top R_{n-m} k\\) 在外推时并不破。破的是 \\(R_{n-m}\\) 所在的相位是否落在训练支持里。</span></p><h3 id="需要一张「距离–维度」对照表" tabindex="-1">需要一张「距离–维度」对照表 <a class="header-anchor" href="#需要一张「距离–维度」对照表" aria-label="Permalink to &quot;需要一张「距离–维度」对照表&quot;">​</a></h3><p>\\(d/2\\) 个平面不是重复的同一个旋转。它们构成从快到慢的频率谱。理解长上下文，就是理解谱的哪一段在目标距离上仍提供可分辨的相位差。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RoPE 的频率取几何级数</p> \\[\\theta_i = \\mathrm{base}^{-2i/d},\\qquad i = 0,1,\\ldots,d/2-1. \\]<p>\\(i=0\\) 时 \\(\\theta_0 = 1\\) 弧度/位置，是最高频；\\(i\\) 增大，\\(\\theta_i\\) 指数下降，最低频约为 \\(\\mathrm{base}^{-1}\\) 量级（以 \\(\\mathrm{base}=10^4\\)、\\(d=128\\) 计，\\(\\theta_{d/2-1}\\approx 1.2\\times 10^{-4}\\)）。位置差 \\(\\Delta = n-m\\) 在第 \\(i\\) 平面上的转角是 \\(\\Delta \\theta_i\\)。</p><p>两个可调对象：</p><ul><li><strong>\\(\\mathrm{base}\\)</strong>：同时缩放整条谱。增大 base，所有 \\(\\theta_i\\) 变小，同样的 \\(\\Delta\\) 对应更小的转角，低频维能覆盖更长的距离才转满一圈。</li><li><strong>对 \\(i\\) 非均匀的缩放</strong>：NTK-aware 一类方法让高频几乎不动（保住短程分辨），低频按长度比拉伸（给长程留相位余量）。YaRN 再把这种非均匀插值与注意力缩放组合。本篇只要知道：它们都是在改 \\(\\theta_i\\)，不是在换一套位置编码。</li></ul><p>训练长度 \\(L\\) 与谱的匹配规则是启发式的：希望在 \\(\\Delta \\approx L\\) 时，仍有若干低频平面的转角显著小于 \\(\\pi\\)，从而远距离不是所有维都正交掉。</p>',17)),(t(),B(i,null,{default:e(()=>[o(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Base%5B%22%E5%9F%BA%E6%95%B0%20base%22%5D%20--%3E%20Theta%5B%22%CE%B8_i%20%3D%20base%20%E7%9A%84%E8%B4%9F%E5%B9%82%22%5D%0A%20%20Theta%20--%3E%20Fast%5B%22%E9%AB%98%E9%A2%91%E5%B9%B3%E9%9D%A2%3A%20%E7%9F%AD%E7%A8%8B%E5%88%86%E8%BE%A8%22%5D%0A%20%20Theta%20--%3E%20Slow%5B%22%E4%BD%8E%E9%A2%91%E5%B9%B3%E9%9D%A2%3A%20%E9%95%BF%E7%A8%8B%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20Slow%20--%3E%20Ext%5B%22%E5%8A%A0%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E6%97%B6%E5%85%88%E5%8A%A8%E8%BF%99%E9%87%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="一圈对应多长" tabindex="-1">一圈对应多长 <a class="header-anchor" href="#一圈对应多长" aria-label="Permalink to &quot;一圈对应多长&quot;">​</a></h3><p>第 \\(i\\) 平面转满 \\(2\\pi\\) 需要 \\(\\Delta = 2\\pi / \\theta_i\\) 个位置。\\(\\theta_i\\) 大（高频），几个 token 就转一圈，适合相邻位置的精细差别；\\(\\theta_i\\) 小（低频），需要成千上万步才转一圈，适合篇章级距离。默认 base \\(=10000\\)、\\(d=128\\) 的头里，最低频的「一圈」已经很长，但仍是为当初的 \\(L\\) 设计的。把 \\(L\\) 乘四而不改 \\(\\theta\\)，等于要求低频维提供它在训练时从未提供过的相位差，同时中频维过早转乱。</p><p><span class="marginnote">代入数字：base \\(=10000\\)、\\(d=128\\) 时，最高频 \\(\\theta_0=1\\)，每个位置转 1 弧度，约 6 个 token 就转一圈——它负责「相邻几个词」的分辨；最低频 \\(\\theta \\approx 1.2\\times 10^{-4}\\)，转一圈要 \\(2\\pi/\\theta \\approx 5.4\\) 万个位置。一根注意力头里同时藏着「秒针」和「万年历」。</span></p><p><span class="marginnote">「转乱」指 \\(\\Delta\\theta_i \\bmod 2\\pi\\) 在训练分布外均匀化，该维对距离不再单调、不再可预测，不是数值溢出。</span></p><h3 id="改-base-是全局慢放" tabindex="-1">改 base 是全局慢放 <a class="header-anchor" href="#改-base-是全局慢放" aria-label="Permalink to &quot;改 base 是全局慢放&quot;">​</a></h3><p>把 base 从 \\(10000\\) 升到 \\(10^6\\) 量级，整条谱左移（更慢）。短程依赖依赖的高频也变慢，相邻位置的分辨可能变差，需要微调来把短程从别的维或从内容里找回来。这是全局改 base 的代价：一根旋钮同时动短程与长程。NTK 风格的非均匀映射就是为了打破这根绑绳——高频 \\(\\theta\\) 接近原值，低频 \\(\\theta\\) 按目标长度压小。YaRN 还处理插值区间与注意力尺度，避免只拉频率、不调 softmax 温度时出现的平均熵漂移。这些名字在长上下文文献里成套出现，是因为它们碰的是同一条 \\(\\theta_i\\) 轴的不同切法。</p><p>全局升 base 与非均匀缩放各牺牲什么、各保什么：</p>',8)),(t(),B(i,null,{default:e(()=>[o(s,{id:"mermaid-81",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%9B%AE%E6%A0%87%EF%BC%9A%E8%AE%AD%E7%BB%83%E9%95%BF%E5%BA%A6%20L%20%E6%89%A9%E5%88%B0%204L%22%5D%20--%3E%20A%5B%22%E7%AD%96%E7%95%A5%E4%B8%80%EF%BC%9A%E5%85%A8%E5%B1%80%E5%8D%87%20base%22%5D%0A%20%20T%20--%3E%20B%5B%22%E7%AD%96%E7%95%A5%E4%BA%8C%EF%BC%9ANTK%20%E5%BC%8F%E9%9D%9E%E5%9D%87%E5%8C%80%E7%BC%A9%E6%94%BE%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E4%BD%8E%E9%A2%91%E5%8F%98%E6%85%A2%EF%BC%9A%E9%95%BF%E7%A8%8B%E6%9C%89%E7%9B%B8%E4%BD%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E9%AB%98%E9%A2%91%E4%B9%9F%E5%8F%98%E6%85%A2%EF%BC%9A%E7%9F%AD%E7%A8%8B%E5%88%86%E8%BE%A8%E5%8F%97%E6%8D%9F%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E4%BD%8E%E9%A2%91%E6%8C%89%E9%95%BF%E5%BA%A6%E6%AF%94%E6%8B%89%E4%BC%B8%EF%BC%9A%E9%95%BF%E7%A8%8B%E7%95%99%E4%BD%99%E9%87%8F%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E9%AB%98%E9%A2%91%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8A%A8%EF%BC%9A%E7%9F%AD%E7%A8%8B%E4%BF%9D%E7%95%99%22%5D%0A%20%20A2%20--%3E%20C%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E9%9C%80%E5%BE%AE%E8%B0%83%E6%89%BE%E5%9B%9E%E7%9F%AD%E7%A8%8B%22%5D%0A%20%20B2%20--%3E%20D%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%8F%92%E5%80%BC%E5%8C%BA%E9%97%B4%E4%B8%8E%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%B8%A9%E5%BA%A6%E8%A6%81%E4%B8%80%E8%B5%B7%E8%B0%83%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">直觉类比：把高频维想成钟表的秒针、低频维想成时针。全局升 base 是把整只表调慢——时针能记更长的日子，但秒针也慢了，近处动作分不清先后；NTK 式缩放是「秒针不动、只放慢时针」，保住近处的精细计时，把慢速部分拉长来覆盖远距离。</span></p><p>训练时直接用更大 base、更大 \\(L\\)，比测试期事后改 \\(\\theta\\) 干净：相位从头到尾在目标距离上见过。事后改谱属于抢救已经训死的 \\(10000\\)，不是频谱设计的第一原则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>只改 base、不微调，短程任务可能立刻掉点。只拉长数据、不改 base，模型在远距离上没有可用的慢维，长上下文继续写，匹配已经与位置无关。两条都要动：数据提供目标距离上的梯度，频谱提供这些距离上仍然可分辨的相位。</p><p>频谱也不是越慢越好。所有 \\(\\theta_i\\) 都接近 0 时，RoPE 退化成几乎无位置，近处的序要靠因果掩码去学，回到 NoPE 的处境。base 的上界是「短程仍有足够快的维」，下界是「目标 \\(L\\) 上仍有足够慢的维」。中间没有与模型无关的最优值，与头宽 \\(d\\) 绑在一起：\\(d\\) 更大，几何级数的档位更多，同一 base 下更能同时覆盖短与长。</p><p><span class="marginnote">常见误区：「外推失败」不是模型「看不远的能力」不足，而是远距离对应的相位差压根没在训练里出现过。改 base / NTK / YaRN 做的事是把新距离重新映射回「模型见过的相位区间」，不是赋予新能力——所以事后改谱几乎总要配一点微调才能把行为稳住。</span></p><p><span class="marginnote">实现里 base 常是 RoPE 的构造参数，和 \\(\\theta\\) 缓存、cos/sin 表绑在一起。测试期改 base 必须重算旋转，已按旧角旋转并写入的 KV 不能直接复用。</span></p><p>本篇不把 YaRN 的分段、注意力温度、NTK 的精确公式展开成步骤清单。需要那些步骤时，应去对应专文。这里只固定三件事：\\(\\theta_i\\) 的定义、base 的全局作用、非均匀改 \\(\\theta\\) 是为了外推时保住短程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>RoPE 的频率 \\(\\theta_i = \\mathrm{base}^{-2i/d}\\) 把维度分成快慢平面：快的分辨短距离，慢的在长距离上仍有相位。增大 base 是全局慢放；NTK / YaRN 一类方法是对 \\(\\theta_i\\) 做非均匀改动并辅以注意力缩放，目的都是外推，而不是新的位置哲学。出处：Su 等的 RoPE 定义（2021/2024）；外推时改谱的动机见后续长上下文工作对 base 与 NTK、YaRN 的使用，那些算法本身不在本篇展开。</p>',10))])}const F=A(l,[["render",h]]);export{T as __pageData,F as default};
